python3 - <<'PY'
import json, os
calls=[]
for p in range(8):
    calls.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":64}})

orders=[0,1,2,3,4,1,5,6]
for i,p in enumerate(orders):
    calls.append({"name":"order_set","arguments":{"position":i,"pattern":p}})

# Helpers
note_names=['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def note(n):
    octv=n//12-1
    return f"{note_names[n%12]}{octv}"

def put(p,r,c,n=None,ins=None,vol=None,e=None,ep=None):
    d={"pattern":p,"row":r,"channel":c}
    if n is not None: d['note']=note(n) if isinstance(n,int) else n
    if ins is not None: d['instrument']=ins
    if vol is not None: d['volume']=vol
    if e is not None: d['effect']=e
    if ep is not None: d['effect_param']=ep
    calls.append({"name":"pattern_set_cell","arguments":d})

# Song materials
prog=[('Am', [57,60,64],45), ('F', [53,57,60],41), ('C', [55,59,62],36), ('G', [55,59,62],43)]
prog2=[('Dm',[53,57,60],38),('F',[53,57,60],41),('E',[56,59,64],40),('E',[56,59,64],40)]
leadA=[69,72,76,72,79,76,72,69,67,69,72,67,64,67,69,72]
leadB=[72,74,76,79,76,74,72,71,72,74,76,79,81,79,76,74]
leadC=[76,79,84,81,79,76,72,74,76,72,69,67,69,72,76,79]
leadD=[64,67,71,67,72,71,67,64,62,64,67,71,72,74,76,79]

# Drum templates per 64-row pattern
for p in range(8):
    for r in range(0,64,4):
        put(p,r,0,24,4,vol=64)  # kick C-1
    for r in [16,48]:
        put(p,r,1,24,5,vol=56)
    for r in range(8,64,8):
        if r not in [16,48]:
            put(p,r,1,24,4,vol=40)
    for r in range(4,64,4):
        put(p,r,2,24,6,vol=30)
    for r in range(2,64,8):
        put(p,r,2,24,6,vol=18)

# Pattern-specific variations
# 0 intro: chords and bass only, sparse hats
for r in range(0,64,8):
    name,ch,b=prog[(r//16)%4]
    for chn,n in zip([4,5,6], ch):
        put(0,r,chn,n,3,vol=28)
    put(0,r,3,b,2,vol=44)
for r in range(4,64,8):
    put(0,r,3,prog[(r//16)%4][2],2,vol=30)
# mute some drums intro
# overwrite by simply not important; clear strong snare/kick? keep groove.

# 1 main A
for r in range(0,64,8):
    ch,b=prog[(r//16)%4][1],prog[(r//16)%4][2]
    for chn,n in zip([4,5,6], ch): put(1,r,chn,n,3,vol=30)
    put(1,r,3,b,2,vol=48)
    put(1,r+4,3,b+7,2,vol=34)
for i,r in enumerate(range(0,64,4)):
    put(1,r,7,leadA[i],1,vol=44)

# 2 variation B
for r in range(0,64,8):
    ch,b=prog2[(r//16)%4][1],prog2[(r//16)%4][2]
    for chn,n in zip([4,5,6], ch): put(2,r,chn,n,3,vol=28)
    put(2,r,3,b,2,vol=50)
    put(2,r+4,3,b+12,2,vol=32)
for i,r in enumerate(range(0,64,4)):
    put(2,r,7,leadB[i],1,vol=46)

# 3 break
for r in range(0,64,8):
    ch,b=prog[(r//16)%4][1],prog[(r//16)%4][2]
    for chn,n in zip([4,5,6], ch): put(3,r,chn,n,3,vol=24)
for r in [0,12,24,36,48,56]:
    put(3,r,3,[45,41,36,43,45,43][[0,12,24,36,48,56].index(r)],2,vol=40)
for i,r in enumerate(range(0,64,8)):
    put(3,r,7,[72,76,79,84,79,76,72,67][i],1,vol=42)
# lighter drums in break
for r in [0,24,32,56]: put(3,r,0,24,4,vol=60)
for r in [16,48]: put(3,r,1,24,5,vol=48)

# 4 lift/build
for r in range(0,64,8):
    ch,b=prog2[(r//16)%4][1],prog2[(r//16)%4][2]
    for chn,n in zip([4,5,6], ch): put(4,r,chn,n,3,vol=30)
    put(4,r,3,b,2,vol=46)
    put(4,r+4,3,b+7,2,vol=30)
for i,r in enumerate(range(0,64,4)):
    put(4,r,7,leadC[i],1,vol=48)
for r in range(0,64,4):
    put(4,r,2,24,6,vol=min(20+r//4,48))

# 5 main return
for r in range(0,64,8):
    ch,b=prog[(r//16)%4][1],prog[(r//16)%4][2]
    for chn,n in zip([4,5,6], ch): put(5,r,chn,n,3,vol=30)
    put(5,r,3,b,2,vol=52)
    put(5,r+4,3,b+7,2,vol=34)
for i,r in enumerate(range(0,64,4)):
    put(5,r,7,leadD[i],1,vol=48)

# 6 outro/loop lead phrase resolving into intro-compatible start
for r in range(0,64,8):
    ch,b=prog[(r//16)%4][1],prog[(r//16)%4][2]
    for chn,n in zip([4,5,6], ch): put(6,r,chn,n,3,vol=26)
    put(6,r,3,b,2,vol=44)
for i,r in enumerate(range(0,64,4)):
    seq=[76,74,72,69,67,64,67,69,72,76,72,69,67,64,60,57]
    put(6,r,7,seq[i],1,vol=42)

# 7 short intro variant to make 8 patterns? use as alt intro if needed; currently unused order length 8 uses patterns above except 7 unused, fill anyway
for r in range(0,64,8):
    ch,b=prog[(r//16)%4][1],prog[(r//16)%4][2]
    put(7,r,3,b,2,vol=40)
    for chn,n in zip([4,5,6], ch): put(7,r,chn,n,3,vol=22)

with open('work/calls.json','w') as f: json.dump(calls,f)
print(len(calls))
